import type { MetadataRoute } from "next";

// Web app manifest — gives Android "Add to Home screen" proper icons and name.
// Icons are generated by `npm run icons` (scripts/generate-icons.mjs).
// display stays "browser": opening from the home screen uses the normal browser
// (shared login cookies). "standalone" would be a separate product decision.
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Gym Tracker",
    short_name: "Gym Tracker",
    description: "Trainings-Protokoll – Übungen, Einstellungen und Verlauf.",
    lang: "de",
    start_url: "/",
    display: "browser",
    background_color: "#f7f6f3",
    theme_color: "#f7f6f3",
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icons/icon-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
